// The 29 bundled Moltys, read from the repo at build time (never copied):
//  - names + .molty file names: device/console/src/catalog/catalog.json (generated by device/console/tools/thumbs.mjs)
//  - fluid-rendered portraits:   device/console/src/catalog/thumbs/<id>.webp (same tool, real renderThumbs())
//  - the .molty files:           device/creatures/molty/<name>.molty (device/creatures/tools/molty-export.mjs)
import catalog from "@molty-catalog/catalog.json";

const THUMBS = import.meta.glob<string>("@molty-catalog/thumbs/*.webp", {
  eager: true,
  import: "default",
  query: "?url",
});
const FILES = import.meta.glob<string>("@molty-files/*.molty", { eager: true, import: "default", query: "?url" });
const byBase = (map: Record<string, string>) =>
  Object.fromEntries(Object.entries(map).map(([path, url]) => [path.split("/").pop()!, url]));
const thumbs = byBase(THUMBS);
const files = byBase(FILES);

export interface Molty {
  id: string;
  name: string;
  thumb: string;
  file: string;
  fileName: string;
}

export const MOLTYS: Molty[] = catalog.creatures.map((c) => ({
  id: c.id,
  name: c.name,
  thumb: thumbs[`${c.id}.webp`] ?? "",
  file: files[c.file] ?? "",
  fileName: c.file,
}));

/** The hero's rotation: a few Moltys with clear silhouettes, then it repeats. */
export const HERO_MOLTYS = ["cute-duck", "cute-frog", "cute-axolotl", "cute-dragon", "cute-octopus", "cute-bunny"];
